package org.crosswire.jsword.index.fts

import okio.FileSystem
import okio.Path
import org.crosswire.jsword.index.analysis.AnalyzedToken
import org.crosswire.jsword.index.analysis.BookAnalyzers
import org.crosswire.jsword.index.fts.query.FtsQueryEvaluator
import org.crosswire.jsword.index.fts.query.LuceneSyntaxParser
import kotlin.random.Random
import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertTrue

/**
 * K6 task 14B: the committed public-domain search fixtures (`jsword/src/commonTest/k6-fixtures/<Module>.tsv`, generated by
 * the Gradle task `generateK6IosFixtures` from the baseline Lucene oracle; embedded as [K6Fixtures] because iOS tests cannot
 * read files). Per module, the 200 fixture verses are indexed into a temporary [FtsIndexStore] from the TSV text (no Book)
 * with the real analyzer of the module's language, and the test asserts
 *  1. the analyzer's tokens (text and positions) equal the baseline's committed tokens for every verse, and
 *  2. every fixture query, through [LuceneSyntaxParser] and [FtsQueryEvaluator], returns exactly the committed baseline result.
 * Runs on the JVM and on the iOS simulator (the iOS run is owed to host CI).
 */
class PdFixtureSearchTest {
    private class Fixture(val module: String, val lang: String, val verses: List<Triple<String, String, String>>,
                          val queries: List<Pair<String, Set<String>>>)

    private fun unescape(s: String): String {
        if ('\\' !in s) return s
        val sb = StringBuilder()
        var i = 0
        while (i < s.length) {
            val c = s[i]
            if (c == '\\' && i + 1 < s.length) {
                sb.append(when (val n = s[i + 1]) { 't' -> '\t'; 'n' -> '\n'; 'r' -> '\r'; else -> n }); i += 2
            } else { sb.append(c); i++ }
        }
        return sb.toString()
    }

    private fun parse(name: String, text: String): Fixture {
        val lines = text.split('\n').filter { it.isNotEmpty() }
        val head = lines.first().split('\t')
        assertEquals("#module", head[0]); assertEquals(name, head[1])
        val split = lines.indexOf("#queries")
        val verses = lines.subList(1, split).map { l -> l.split('\t').let { Triple(it[0], unescape(it[1]), it[2]) } }
        val queries = lines.drop(split + 1).map { l ->
            val p = l.split('\t')
            unescape(p[0]) to (p.getOrElse(1) { "" }.split(' ').filter { it.isNotEmpty() }.toSet())
        }
        return Fixture(name, head[2], verses, queries)
    }

    /** The baseline probe's rendering: terms joined by a space, `@n` when the position increment is not 1. */
    private fun render(tokens: List<AnalyzedToken>): String {
        val sb = StringBuilder()
        var previous = -1
        for ((i, t) in tokens.withIndex()) {
            if (i > 0) sb.append(' ')
            sb.append(t.text)
            val increment = t.position - previous
            if (increment != 1) sb.append('@').append(increment)
            previous = t.position
        }
        return sb.toString()
    }

    @Test fun fixturesAreEmbedded() {
        assertEquals(setOf("ChiUn", "ChiUns", "CzeBKR", "FreCrampon", "GerBoLut", "GreVamvas", "JapKougo", "RusSynodal"),
            K6Fixtures.files().keys)
    }

    @Test fun analyzerTokensAndQueryResultsMatchTheBaselineOracle() {
        val failures = ArrayList<String>()
        var queries = 0
        for ((name, text) in K6Fixtures.files()) {
            val fx = parse(name, text)
            assertEquals(200, fx.verses.size, name)
            assertTrue(fx.queries.size >= 8, "$name has ${fx.queries.size} queries")
            val analyzer = BookAnalyzers.forLanguage(fx.lang)
            val path: Path = FileSystem.SYSTEM_TEMPORARY_DIRECTORY / "k6-fixture-$name-${Random.nextLong().toString(16)}.db"
            val store = FtsIndexStore.create(path)
            try {
                store.beginBuild()
                val refByRow = HashMap<Long, String>()
                fx.verses.forEachIndexed { i, (ref, verseText, oracleTokens) ->
                    val tokens = analyzer.analyze(verseText)
                    val got = render(tokens)
                    if (got != oracleTokens) failures += "$name $ref tokens: expected '$oracleTokens' but got '$got'"
                    store.addEntry(i + 1L, ref, tokens, emptyList())
                    refByRow[i + 1L] = ref
                }
                store.writeMetadata(FtsIndexMetadata(FTS_SCHEMA_VERSION, BookAnalyzers.analyzerId(fx.lang), SearchTokenCodec.ID, name, "1.0", "fixture"))
                store.commitBuild()
                val evaluator = FtsQueryEvaluator(store, analyzer)
                for ((q, expected) in fx.queries) {
                    queries++
                    val got = evaluator.evaluate(LuceneSyntaxParser.parse(q, analyzer)).map { refByRow.getValue(it) }.toSet()
                    if (got != expected) failures += "$name query '$q': expected ${expected.sorted()} but got ${got.sorted()}"
                }
            } finally {
                store.close()
                FileSystem.SYSTEM.delete(path)
            }
        }
        assertTrue(queries >= 80, "only $queries queries")
        assertTrue(failures.isEmpty(), "${failures.size} mismatches:\n" + failures.take(20).joinToString("\n"))
    }
}
